/**
 * JSSDM Reference Desk — offline-capability service worker.
 *
 * Strategy: RUNTIME caching (network-first, falling back to cache; every
 * successful same-origin GET response is cached as it's fetched), not a
 * build-time precache manifest. This is a deliberate tradeoff, not an
 * oversight — Vite emits hashed asset filenames (e.g. index-a1b2c3.js) that
 * change on every build, so a hand-written precache list here would go
 * stale the moment the app is rebuilt unless it's generated by a
 * build-time tool (e.g. vite-plugin-pwa/Workbox) wired into the bundler.
 * That integration could not be verified in the environment this was
 * built in (no working package-manager install of the build toolchain was
 * available to confirm it compiles), so this hand-written, framework-free
 * worker was chosen instead: it costs one extra network round trip the
 * very first time each asset is fetched, but every asset actually used
 * ends up cached after that, and it never depends on knowing filenames in
 * advance. See the Phase 1 report for the honest tradeoff writeup.
 *
 * What this worker does:
 *  - Same-origin GET requests: try the network first; on success, clone the
 *    response into the cache and return it. On failure (offline), fall back
 *    to whatever's cached for that exact URL.
 *  - Navigation requests (loading the page itself) additionally fall back
 *    to the cached app shell ("/") if the exact URL isn't cached — this app
 *    has no client-side routing (App.tsx switches views with in-memory
 *    state, not the URL), so "/" IS the whole app shell.
 *  - /.netlify/functions/* (the AI proxy) is NEVER cached and NEVER served
 *    from cache — those requests always go straight to the network, and a
 *    failure there is a real failure, not something to paper over with
 *    stale data. AI is explicitly online-only.
 *  - Non-GET requests (POSTs, including the AI call) are never intercepted
 *    at all — passthrough only.
 */

const CACHE_NAME = "jssdm-runtime-v2"; // bumped: forces eviction of previously
// cached favicon/icon/manifest responses (favicon.ico, icon.svg,
// logo-crest-240.png, manifest.webmanifest) after the logo/icon swap below —
// see the existing activate handler, which already deletes any cache whose
// name doesn't match CACHE_NAME.
const AI_PATH_PREFIX = "/.netlify/functions/";

self.addEventListener("install", (event) => {
  // Activate this worker as soon as it's installed, without waiting for
  // every open tab of the previous version to close.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter((n) => n !== CACHE_NAME).map((n) => caches.delete(n)));
      await self.clients.claim();
    })(),
  );
});

function isAIRequest(url) {
  return url.pathname.startsWith(AI_PATH_PREFIX);
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return; // never intercept POSTs (the AI call, etc.)

  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // same-origin only
  if (isAIRequest(url)) return; // AI proxy: always network, never cached, never served stale

  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      try {
        const fresh = await fetch(req);
        if (fresh && fresh.ok) {
          cache.put(req, fresh.clone());
        }
        return fresh;
      } catch (err) {
        const cached = await cache.match(req);
        if (cached) return cached;
        if (req.mode === "navigate") {
          const shell = await cache.match("/");
          if (shell) return shell;
        }
        throw err;
      }
    })(),
  );
});
